# Build the test grid from its regular panel layout, then apply the ordered path bridges.
grid = [[1]*30 for _ in range(30)]
# 3x3 panels, each 6x6 of background 8, separated by color 1.
row_starts = [1,9,16]
col_starts = [1,10,20]
for r0 in row_starts:
    for c0 in col_starts:
        for r in range(r0,r0+6):
            for c in range(c0,c0+6):
                grid[r][c] = 8
colors = [[2,4,3],[3,6,9],[9,4,5]]
for ri,r0 in enumerate(row_starts):
    for ci,c0 in enumerate(col_starts):
        color=colors[ri][ci]
        for r in range(r0+2,r0+4):
            for c in range(c0+2,c0+4):
                grid[r][c]=color
# ordered sequence route: 2(top-left)->4(top-middle)->3(top-right)->9(mid-right)
# ->5(bottom-right)->4(bottom-middle)->6(mid-center)->3(mid-left)->9(bottom-left)
# Draw each panel's color through the separator toward its successor.
for r in (3,4):
    for c in range(7,10): grid[r][c]=2   # top-left -> top-middle
for r in (3,4):
    for c in range(16,20): grid[r][c]=4 # top-middle -> top-right
for r in (7,8):
    for c in (22,23): grid[r][c]=3     # top-right -> middle-right
for c in (22,23): grid[15][c]=9        # middle-right -> bottom-right
for r in (18,19):
    for c in range(16,20): grid[r][c]=5 # bottom-right -> bottom-middle
for c in (12,13): grid[15][c]=4        # bottom-middle -> middle-center
for r in (11,12):
    for c in range(7,10): grid[r][c]=6 # middle-center -> middle-left
for c in (3,4): grid[15][c]=3          # middle-left -> bottom-left
# clue row
clue=[1,2,1,4,1,3,1,9,1,5,1,4,1,6,1,3,1,9]+[1]*12
grid[28]=clue
print(len(grid), set(map(len,grid)))
for i,row in enumerate(grid): print(i,' '.join(map(str,row)))
